import{_ as t,o as n,c as o,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Crimson/SeaStore Meeting 2022-07-06","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore Meeting 2022-07-06","date":"2022-07-06T00:00:00.000Z","updated":"2022-07-20T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Crimson_SeaStore_Meeting_2022-07-06.md","filePath":"posts/2022/Ceph_Crimson_SeaStore_Meeting_2022-07-06.md","lastUpdated":1780460162000}'),l={name:"posts/2022/Ceph_Crimson_SeaStore_Meeting_2022-07-06.md"};function r(s,i,a,p,g,S){return n(),o("div",null,[...i[0]||(i[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2022年7月6日（具体日期未提及）</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： Yingjin、Fair、Marvin、Kingston、Aravind、Jinyu、Juan、Sam等</p><p><strong>会议内容</strong>：</p><p><strong>一、人员变动与项目进展</strong></p><ol><li><strong>人员变动</strong>： Yingjin 将担任 C-Store 精英，负责 C-Store 项目的领导工作。</li><li><strong>项目进展</strong>： <ul><li>C-Store 项目：Yingjin 继续负责 C-Store 项目，并担任技术领袖。</li><li>ZNS 驱动开发： <ul><li>Aravind 正在开发 ZNS 驱动，已提交三个补丁，但遇到 make check 失败问题。</li><li>Kingston 提到 ZNS 区的更新问题，由于关闭操作会导致磁盘无法再次打开，需要进行修改。</li><li>会议讨论了 ZNS 驱动的关闭操作与磁盘容量浪费的问题，决定修改 ZNS 管理器，使其在写入数据时填充空间，以避免浪费。</li></ul></li><li>垃圾回收器改进：Jinyu 提出关于垃圾回收器改进的想法，建议在 GC 事务中添加判断逻辑，以避免将不满足时间局部性原则的 extent 添加到 Aerial 中。</li><li>对象存储改进：Juan 正在调试对象存储相关的 PR，并尝试实现 KBB 树优化。</li><li>性能测试：Sam 询问如何测试 ZNS 驱动，建议使用 fio 或 rados-bench 等工具进行性能测试。</li></ul></li></ol><p><strong>二、讨论与决策</strong></p><ol><li><strong>ZNS 驱动开发</strong>： <ul><li>Aravind 将修改 ZNS 管理器，使其在写入数据时填充空间，以避免浪费。</li><li>Sam 将审查 Aravind 提交的补丁，并请求代码审查。</li></ul></li><li><strong>垃圾回收器改进</strong>： <ul><li>Jinyu 的建议被认可，将考虑将其纳入垃圾回收器改进方案。</li></ul></li><li><strong>对象存储改进</strong>： <ul><li>Juan 将继续调试对象存储相关的 PR，并尝试实现 KBB 树优化。</li></ul></li></ol><p><strong>三、行动计划</strong></p><ol><li>Aravind 修改 ZNS 管理器，并提交补丁。</li><li>Sam 审查 Aravind 提交的补丁，并请求代码审查。</li><li>Jinyu 将垃圾回收器改进方案提交给相关团队进行讨论。</li><li>Juan 继续调试对象存储相关的 PR，并尝试实现 KBB 树优化。</li></ol><p><strong>四、其他事项</strong></p><ol><li>会议讨论了 ZNS 驱动的测试方法，建议使用 fio 或 rados-bench 等工具进行性能测试。</li><li>会议讨论了 ZNS 驱动的容量浪费问题，并决定修改 ZNS 管理器，使其在写入数据时填充空间。</li></ol><p><strong>五、结束语</strong></p><p>本次会议讨论了 C-Store 项目、ZNS 驱动开发、垃圾回收器改进、对象存储改进等议题，并制定了相应的行动计划。会议进展顺利，达到了预期目标。</p>',15)])])}const u=t(l,[["render",r]]);export{d as __pageData,u as default};
